"A GitHub user or organization: every project of it is listed.": "Un utente o un’organizzazione GitHub: vengono elencati tutti i suoi progetti.",
"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Un server Model Context Protocol offre a un agente di programmazione strumenti aggiuntivi: file, web, un browser, GitHub e simili. Funziona solo con gli agenti che accedono tramite il proprio strumento a riga di comando in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode): un agente usato solo con una chiave API non può usarne uno qui.",
"A Wear OS watch can be reached over its Bluetooth link to the phone, with no Wi-Fi. This phone then talks to the watch through its own ADB.": "Un orologio Wear OS è raggiungibile tramite il collegamento Bluetooth con il telefono, senza Wi-Fi. Questo telefono comunica poi con l’orologio tramite il proprio ADB.",
