"After a successful install, ask whether to delete the installer file (it goes to a hidden folder first, with an Undo)": "Dopo un'installazione riuscita, chiedi se eliminare il file di installazione (prima va in una cartella nascosta, con Annulla)",
"Agent websites": "Siti web degli agenti",
"Agent when the app opens": "Agente all’apertura dell’app",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Gli agenti agiscono tramite quattro tipi di passaggi: eseguire un comando, leggere un file, scrivere un file o modificarne una parte. Prima che un comando venga eseguito o che un file cambi, vedi esattamente cosa verrà fatto e scegli Esegui (o Applica), Salta oppure Consenti sempre per il resto della chat. La lettura dei file nella cartella corrente non richiede conferma.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Gli agenti possono sbagliare. Leggi cosa vogliono eseguire, soprattutto con Modalità operativa o Root, dove un comando può rimuovere app o modificare impostazioni.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Gli agenti vedono solo ciò che invii e ciò che restituiscono i loro passaggi; chiavi e token presenti nell’output vengono loro nascosti.",
