"App: ADB Application Manager Pro ? (build ?)": "App: ADB Application Manager Pro ? (build ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner può svuotare le cache che nessun accesso ai file raggiunge (il pulsante «Svuota cache» della schermata Archiviazione di un’app) toccando al posto tuo nelle impostazioni di sistema. Per farlo ha bisogno del servizio di accessibilità di questa app. Il servizio agisce solo mentre AppCleaner svuota le cache: apre la schermata Info app di un’app dopo l’altra, tocca Svuota cache e si ferma quando lo schermo si spegne o si blocca. Una copertura sullo schermo mostra cosa sta facendo, con un modo per annullare. Nulla viene letto o inviato altrove. Su Android 13 e versioni successive, un’app installata da un file può richiedere prima «Consenti impostazioni con restrizioni» (Info app di questa app, menu a tre puntini).",
