"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store è un client open source per Play Store. Il rilevamento automatico della versione su Play è previsto in futuro (richiede l’autenticazione anonima a Play); per ora indirizza ogni app alla sua pagina dello store, aprendo Aurora Store se è installato.",
