"Browser Use did not start the task.": "Browser Use non ha avviato l'attività.",
"Browser Use failed before it had an answer.": "Browser Use ha fallito prima di avere una risposta.",
"Browser Use finished without an answer.": "Browser Use ha finito senza una risposta.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use è l'agente browser open source; questo è il suo cloud ospitato, con un livello gratuito per i nuovi account. Un pulsante Ask agent avvia una breve attività nel browser che cerca la domanda sul web: può richiedere un minuto o due e consuma un po' di credito. Serve solo ai pulsanti Ask agent, non è una chat. Provare la chiave non costa nulla.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use ha impiegato troppo tempo (oltre 4 minuti). Riprova più tardi.",
"Browser Use was stopped before it had an answer.": "Browser Use è stato fermato prima di avere una risposta.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Automazione del browser. Richiede Node e il download di Chromium, che può essere pesante su un telefono.",
