"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Per cambiare il tema e gli overlay serve la shell. In Modalità operative connettine una, poi torna qui.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Per cambiare il tema e gli overlay serve la shell. In Modalità operative connettine una, poi torna qui. I colori attualmente in uso sono visibili anche senza.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "Cambiare questo valore può compromettere la configurazione, le app o il sistema. Cambialo solo se sai cosa fa.",
