"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Scegli il metodo di accesso nella schermata di connessione dell’agente. Gli strumenti senza una versione per Android vengono installati in un ambiente Debian dentro Termux. Ci vogliono diversi minuti e fino a circa 1 GB; i provider non supportano ufficialmente Android, quindi uno strumento potrebbe non funzionare su tutti i telefoni.",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "Scegli la versione e tocca il suo pulsante di download. Il file viene salvato qui e il browser si chiude da solo.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Scegli cosa fa il pulsante extra su ogni riga dell’elenco App. È sempre un’icona e quelle che cambiano in base all’app (Attiva / Disattiva, Installa / Disinstalla, Riattiva / Sospendi) cambiano icona e azione in base allo stato attuale dell’app.",
"Choose what to install and which starter files to write": "Scegli cosa installare e quali file iniziali scrivere",
"Choosing a folder needs the app build": "Scegliere una cartella richiede la versione app",
