"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro o Max e l’accesso con un account Google si possono usare solo nelle app dei rispettivi provider: Anthropic e Google non consentono ad altre app di usarli. Per questo il Terminale ti fa accedere tramite gli strumenti a riga di comando ufficiali in esecuzione in Termux, dove si apre la pagina di accesso del sito del provider:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Pulisci ciò che non serve più: file superflui, dati eliminabili delle app, residui di app scomparse e file presenti due volte. Prima esegui la scansione, guarda l’elenco, togli ciò che vuoi tenere, poi elimina. I quattro strumenti usano la modalità operativa di questa app per le cartelle che un’app normale non può leggere.",
"Clean — no engine flagged this file": "Pulito — nessun motore antivirus ha segnalato questo file",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "La pulizia è simulata. I file vengono analizzati e segnalati, ma in realtà non viene eliminato nulla.",
