"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI non ha trovato una risposta. Prova la ricerca web o un altro agente.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI è il crawler web open source; questo è il suo cloud ospitato. Un nuovo account riceve crediti gratuiti e una quota mensile gratuita, senza carta. Un pulsante Ask agent invia la domanda al suo servizio di risposte, che cerca sul web, legge le pagine e scrive la risposta. Serve solo ai pulsanti Ask agent, non è una chat. La prova consuma un credito.",
