"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Ogni agente conserva questa informazione nel proprio file, come fa il suo accesso ufficiale, quindi due o più agenti possono avere lo stesso server e ciascuno può usarlo. Codex conserva il token di un server remoto come variabile d’ambiente anziché nel suo file. Non testato con ogni versione di ogni strumento.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Ogni shell ha il proprio schermo e resta aperta mentre usi altre schede: cd, export e variabili restano validi da un comando all’altro. Riavvia shell ne avvia una nuova.",
"Each wait is 600 seconds (10 minutes) at most.": "Ogni attesa dura al massimo 600 secondi (10 minuti).",
"Earlier certificates (the signing key was changed)": "Certificati precedenti (la chiave di firma è stata cambiata)",
