"Errors": "Errori",
"Errors only": "Solo errori",
"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Tutte le app del catalogo F-Droid o di uno qualsiasi dei repository di terze parti noti. Scegli un repository, sfoglia per categoria e installa direttamente — i download vengono verificati con lo SHA-256 pubblicato dal repository.",
"Every app that is not enabled is saved.": "Ogni app non attiva viene salvata.",
"Every change goes into the history, so it can be reverted.": "Ogni modifica va nella cronologia, quindi può essere annullata.",
"Every level is hidden - tap the color key above to show some.": "Tutti i livelli sono nascosti — tocca la legenda colori qui sopra per mostrarne alcuni.",
"Every palette has a light and a dark version": "Ogni tavolozza ha una versione chiara e una scura",
"Every setting here goes back to what SD Maid SE ships with.": "Ogni impostazione qui torna a ciò che SD Maid SE offre di serie.",
"Every source is off. Turn some on in Settings.": "Tutte le fonti sono disattivate. Attivane qualcuna nelle Impostazioni.",
"Every uninstall, disable and restore, with one-tap undo": "Ogni disinstallazione, disattivazione e ripristino, con annullamento con un solo tocco",
"Everything is up to date": "Tutto aggiornato",
"Everything is up to date.": "Tutto è aggiornato.",
"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa non ha trovato risposta a questa. Prova la ricerca web o un altro agente.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa è un motore di ricerca creato per l'IA. Il suo servizio di risposte cerca sul web e scrive una breve risposta che cita le fonti. Un nuovo account riceve crediti gratuiti. Provare la chiave esegue una piccola ricerca (una frazione di centesimo). Un pulsante Ask agent gli invia la domanda; non viene inviato nulla finché non ne premi uno.",
