"Format": "Formato",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Trovati leggendo i nomi delle classi nel codice dell’app su questo telefono; nulla viene inviato altrove. Elenco dei tracker: Exodus Privacy, con licenza ODbL 1.0. Il codice rinominato da un riduttore (R8, ProGuard) o caricato in seguito può nascondere un tracker, quindi un numero basso non è una prova che non ce ne siano.",
