"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Congela, rimuovi il bloatware, installa, fai il backup e ispeziona ogni app del tuo telefono, direttamente dal telefono: tramite ADB, Debug wireless, Shizuku o Root. Nessun computer, nessun account, nessuna pubblicità.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Da Gestione file: installazione tramite un backend con privilegi, con i controlli di firma di questa app disattivati. Android verifica comunque le firme da solo: un APK la cui firma non può essere verificata viene firmato con la chiave di questa app e installato, e un’app firmata da qualcun altro può essere sostituita solo dopo averla disinstallata (prima ti viene chiesto).",
