"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse e Deepseek si connettono con una chiave API dal sito del fornitore (link qui sotto). L’uso viene fatturato dal fornitore all’account di quella chiave; anche l’API Gemini di Google ha un livello gratuito, in cui Google può usare ciò che invii per migliorare i propri prodotti.",
