"Invalid source URL: the address must point to a GitHub or GitLab repository, or to a .json metadata file.": "URL della fonte non valido: l’indirizzo deve puntare a un repository GitHub o GitLab, o a un file di metadati .json.",
"Invalid source URL: the address must start with https.": "URL della fonte non valido: l’indirizzo deve iniziare con https.",
