"Its patches are removed from this phone. Apps you already patched stay as they are.": "Le sue patch vengono rimosse da questo telefono. Le app già modificate restano come sono.",
"Its settings, accounts and files on the device are deleted.": "Le sue impostazioni, i suoi account e i suoi file sul dispositivo vengono eliminati.",
