"Not for this version": "Non per questa versione",
"Not found on USB. Check the cable, unlock the device and make sure USB debugging is on, then try again.": "Non trovato via USB. Controlla il cavo, sblocca il dispositivo e assicurati che il debug USB sia attivo, poi riprova.",
"Not found on this phone. Enter the address of the computer that runs it, then Connect.": "Non trovato su questo telefono. Inserisci l’indirizzo del computer su cui è in esecuzione, poi tocca Connetti.",
