"Not in the list? Search the whole catalog for": "Non è nell’elenco? Cerca in tutto il catalogo:",
"Not in use: the theme above is a curated palette. Choose a style to build one from the source color.": "Non in uso: il tema qui sopra è una palette selezionata. Scegli uno stile per crearne uno dal colore di origine.",
