"Nothing found. Both devices must be on the same Wi-Fi network, with wireless debugging on. You can also type the address by hand under Wi-Fi.": "Nessun risultato. Entrambi i dispositivi devono essere sulla stessa rete Wi-Fi, con il debug wireless attivo. Puoi anche scrivere l’indirizzo a mano in Wi-Fi.",
"Nothing found. Keep the Wireless Debugging screen open and enter the ports manually.": "Nessun risultato. Tieni aperta la schermata Debug wireless e inserisci le porte manualmente.",
