"Off": "Disattivato",
"Off by default": "Disattivato per impostazione predefinita",
"Off:": "Disattivato:",
"Off: reading outside the current folder needs your OK.": "Disattivato: per leggere fuori dalla cartella corrente serve la tua conferma.",
"Off: the patches that work are applied and the failed ones are reported.": "Disattivato: le patch che funzionano vengono applicate e quelle non riuscite vengono segnalate.",
"Offer to delete the file afterwards": "Proponi di eliminare il file al termine",
"Offline cache": "Cache offline",
"Offline: showing what was loaded": "Offline: vengono mostrati i dati caricati",
"Old": "Vecchio",
"Older version": "Versione precedente",
"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (sul dispositivo)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama non è ancora in esecuzione su questo telefono. Installalo qui sotto oppure inserisci l’indirizzo di un computer su cui è in esecuzione.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama esegue un modello per il codice direttamente su questo telefono: gratis, e offline una volta scaricato il modello. Si installa in Termux; i modelli piccoli (da 1,5B a 3B) vanno meglio su un telefono. Funziona anche Ollama su un computer: fallo ascoltare su tutti gli indirizzi e inserisci qui l'indirizzo del computer (come 192.168.1.20:11434/v1).",
"On": "Attivato",
"On device": "Sul dispositivo",
"On this phone": "Su questo telefono",
"On:": "Attivato:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Un comando alla volta per shell; l’output lungo viene accorciato sullo schermo e in ciò che viene inviato a un agente.",
"One file only": "Un solo file",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Una chiave per l’intera app. La scansione del programma di installazione e quella di Morphe Helper la usano entrambe; nessuna la chiede di nuovo, rimandano qui solo quando manca.",
"One more place to find apps": "Un altro posto dove trovare app",
"One package per line. Duplicate entries are removed automatically.": "Un pacchetto per riga. I duplicati vengono rimossi automaticamente.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Un colore di origine, nove modi per trasformarlo in un tema completo: l’accento, lo sfondo, le schede e il testo, in chiaro e in scuro. Scegliere uno stile crea il tema dal colore di origine qui sotto.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Lo usa solo AppCleaner: apre la schermata Info app del sistema di ogni app e tocca Svuota cache, per le cache che nessun accesso ai file raggiunge. Non fa altro, non legge mai ciò che è sullo schermo a parte quelle schermate e si ferma quando lo schermo si spegne.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "In questi file viene scritto solo un blocco contrassegnato; ciò che c’è già resta, e rieseguire questa operazione aggiorna il blocco invece di aggiungerne un altro.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Aggiungi solo fonti di cui ti fidi. Una fonte di patch decide cosa finisce nelle tue app modificate.",
"Only apps installed on this phone": "Solo app installate su questo telefono",
"Only base": "Solo base",
"Only hidden files are here. Tick Show hidden files to see them.": "Qui ci sono solo file nascosti. Seleziona Mostra file nascosti per vederli.",
"Only include common media files, documents and archives.": "Includi solo i comuni file multimediali, documenti e archivi.",
"Only list what would run for each app. Nothing is run.": "Elenca solo ciò che verrebbe eseguito per ogni app. Non viene eseguito nulla.",
"Only patches for apps installed on this phone": "Solo patch per app installate su questo telefono",
"Only split bundles are listed for this app. Turn on Allow split APK.": "Per questa app sono elencati solo bundle suddivisi. Attiva Consenti APK suddivisi.",
"Only text and compiled XML files can be compared line by line": "Solo i file di testo e XML compilati possono essere confrontati riga per riga",
"Only the app name you typed is sent.": "Viene inviato solo il nome dell'app digitato.",
"Only the lines written by the app you pick": "Solo le righe scritte dall’app che scegli",
"Only the selected apps are saved.": "Vengono salvate solo le app selezionate.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Cambia solo il testo di questa app; nomi, percorsi e comandi nei riquadri di codice mantengono il proprio carattere.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "A lui viene inviata solo questa domanda di esempio: se il pacchetto Calcolatrice può essere disattivato.",
