"Patches from different sources are built independently and can conflict. Sticking to one source per app is the safe default. Continue?": "Le patch di fonti diverse vengono create in modo indipendente e possono entrare in conflitto. Usare una sola fonte per app è la scelta sicura predefinita. Continuare?",
