"Perplexity": "Perplexity",
"Phone makers and apps add settings of their own.": "I produttori di telefoni e le app aggiungono impostazioni proprie.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Scegli un pacchetto di patch .mpp dall’archiviazione. Una fonte locale non si aggiorna mai da sola: scegli il nuovo file quando esce.",
"Pick a Coding Agent in the Terminal first": "Scegli prima un agente di programmazione nel Terminale",
"Pick a package file to read it and choose how to install it.": "Scegli un file pacchetto per leggerlo e decidere come installarlo.",
"Pick a package first": "Scegli prima un pacchetto",
"Pick an agent under Coding Agents to chat": "Scegli un agente in Agenti di programmazione per chattare",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Scegli un agente, poi il modello e l’impegno (Basso, Bilanciato o Alto: quanto gli viene chiesto di ragionare). La prima volta entrambi partono da una scelta bilanciata e l’agente chiede ciò che gli serve (una chiave API, un indirizzo di server o un accesso) e lo verifica prima che tu inizi.",
"Pick at least one agent": "Scegli almeno un agente",
