"Termux answered. All set.": "Termux ha risposto. Tutto pronto.",
"Termux could not be opened. Is it installed?": "Impossibile aprire Termux. È installato?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux non accetta ancora comandi da altre app. In Termux, esegui:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux non accetta ancora comandi da altre app: esegui in Termux il comando del passaggio 3, poi verifica di nuovo.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux è gratuito. Scaricalo da F-Droid o GitHub; la vecchia versione di Google Play non è adatta.",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termux non è installato. È gratuito su F-Droid o GitHub.",
"Termux is not set up for this app yet.": "Termux non è ancora configurato per questa app.",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux è pronto: vim, nano, git e python sono installati e bash ha il suo .bashrc iniziale. Apri il terminale reale per i programmi a schermo intero.",
"Termux permission": "Autorizzazione Termux",
