"That password did not work. Try again.": "La password non è corretta. Riprova.",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "Questo pattern potrebbe bloccare l’elenco (una ripetizione dentro una ripetizione, oppure molto lungo), quindi viene cercato come testo semplice.",
"That port is used by this phone's own ADB. Use another, like 4444.": "Quella porta è usata dall’ADB di questo telefono. Usane un’altra, come 4444.",
