"That source did not work": "Quella fonte non ha funzionato",
"That source did not work Trying the other sources...": "Quella fonte non ha funzionato. Provo le altre fonti...",
"The # button switches to commands.": "Il pulsante # passa ai comandi.",
"The $ button switches to commands.": "Il pulsante $ passa ai comandi.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "La chiave ADB e la chiave di firma degli APK vengono create su questo telefono e non lo lasciano mai.",
"The APK": "L’APK",
"The APK is ready (saved from the browser).": "L’APK è pronto (salvato dal browser).",
"The APK is ready.": "L’APK è pronto.",
"The Action Button": "Il Pulsante azione",
"The Bluetooth link could not be set up.": "Impossibile configurare il collegamento Bluetooth.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "Il pulsante MCP apre una schermata per dare a un agente strumenti aggiuntivi (file, web, un browser, GitHub...) tramite il Model Context Protocol. Scegli un preset o scrivi il tuo: un nome, un comando locale o un indirizzo remoto, ed eventuali chiavi o header necessari. Scegli a quali agenti aggiungerlo: lo stesso server può andare in due o più agenti contemporaneamente, perché ogni agente lo conserva nel proprio file.",
"The Morphe engine is not in this build of the app": "Il motore Morphe non è presente in questa versione dell’app",
"The PDF could not be shown.": "Impossibile mostrare il PDF.",
"The Play Store gives no download to other apps. This opens the app's page in the Play Store.": "Il Play Store non permette il download ad altre app. Si apre la pagina dell'app nel Play Store.",
"The Rish shell ended. Tap Rish mode to open a new one.": "La shell Rish è terminata. Tocca Modalità Rish per aprirne una nuova.",
"The Rish shell is no longer running.": "La shell Rish non è più in esecuzione.",
"The Terminal needs the app (it is not available in a plain browser)": "Il Terminale richiede l’app (non è disponibile in un normale browser)",
"The UAD-NG list has not been downloaded yet.": "L’elenco UAD-NG non è ancora stato scaricato.",
"The UAD-NG list has nothing on this app": "L’elenco UAD-NG non ha nulla su questa app",
"The VirusTotal scan did not work": "La scansione di VirusTotal non ha funzionato",
"The VirusTotal scan did not work.": "La scansione di VirusTotal non è riuscita.",
"The accessibility service is not ready": "Il servizio di accessibilità non è pronto",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Il servizio di accessibilità non è pronto (non è connesso), quindi le cache che solo lui può svuotare restano. Dopo, usa «Cancella il resto con l’accessibilità» nella scheda di AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Il servizio di accessibilità non è pronto (è disattivato), quindi le cache che solo lui può svuotare restano. Dopo, usa «Cancella il resto con l’accessibilità» nella scheda di AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Il servizio di accessibilità non è pronto (consenso non dato), quindi le cache che solo lui può svuotare restano. Dopo, usa «Cancella il resto con l’accessibilità» nella scheda di AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "L’account ha esaurito il credito oppure è stato raggiunto un limite di spesa.",
"The agent is still working: STOP it first": "L’agente sta ancora lavorando: prima premi STOP",
"The agent pauses after this many steps.": "L’agente si ferma dopo questo numero di passaggi.",
"The app": "L’app",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "L’app è gratuita e lo resterà. Se ti ha fatto risparmiare tempo, un caffè mi aiuta a continuare a migliorarla. È del tutto facoltativo, e grazie!",
"The app version, Android version and phone model, so a problem is easier to find.": "La versione dell’app, la versione di Android e il modello del telefono, per trovare più facilmente un problema.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Qui sono elencate le app che modifichi, con il log di ogni esecuzione, così puoi reinstallarle, condividerle o salvarle in Download.",
"The archive file is rewritten without this file.": "Il file di archivio viene riscritto senza questo file.",
"The archive file is rewritten without this folder and everything in it.": "Il file di archivio viene riscritto senza questa cartella e tutto il suo contenuto.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "L'archivio viene eliminato solo se tutti i suoi file sono stati estratti, senza saltarne nessuno.",
