"The edit could not start": "Impossibile avviare la modifica",
"The exclusions SD Maid SE ships with come back, the ones you removed too. Yours stay.": "Tornano le esclusioni fornite con SD Maid SE, anche quelle che avevi rimosso. Le tue restano.",
"The exclusions could not be read.": "Impossibile leggere le esclusioni.",
"The extra button on every row of the Apps list. Choose what a tap on it does. Press and hold it on a row for a sheet with every action for that app.": "Il pulsante extra su ogni riga dell’elenco App. Scegli cosa fa un tocco su di esso. Tienilo premuto su una riga per una scheda con tutte le azioni per quell’app.",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "I tasti extra funzionano come quelli di Termux: ESC cancella la riga, TAB completa un nome di file, CTRL-C interrompe ciò che è in esecuzione, le frecce scorrono i comandi precedenti e spostano il cursore, HOME e END saltano all’inizio e alla fine della riga, e | / - ~ ci sono perché le tastiere dei telefoni li nascondono.",
"The extraction could not start": "Impossibile avviare l'estrazione",
"The file": "Il file",
"The file and its log are removed. The app on the phone is not touched.": "Il file e il suo log vengono rimossi. L’app sul telefono non viene toccata.",
"The file chooser needs the app build": "Il selettore di file richiede la versione dell'app",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "Il file viene rimosso dall’archiviazione di questo telefono, non solo dall’elenco. Una barra Annulla resta visibile per alcuni secondi e il file sparisce definitivamente solo quando la barra scompare.",
"The file was saved, but it is not an app file (unknown). Choose another download in the browser.": "Il file è stato salvato, ma non è un file di app (sconosciuto). Scegli un altro download nel browser.",
"The fingerprint is shown in the app build": "L’impronta digitale è mostrata nella build dell’app",
"The folder": "La cartella",
"The folder and everything in it is removed from the device.": "La cartella e tutto il suo contenuto vengono rimossi dal dispositivo.",
"The font could not be loaded, so the system font is used.": "Impossibile caricare il carattere, quindi viene usato quello di sistema.",
"The font file is missing.": "Il file del carattere non c'è.",
"The font of the text in this app. It does not change the font of the rest of your phone.": "Il carattere del testo di questa app. Non cambia il carattere del resto del telefono.",
"The font search needs the app build": "La ricerca di caratteri richiede la versione dell'app",
"The font the system uses": "Il carattere usato dal sistema",
"The full information could not be loaded: unknown error": "Impossibile caricare le informazioni complete: errore sconosciuto",
"The full path on the device.": "Il percorso completo sul dispositivo.",
