"The install did not work": "L’installazione non ha funzionato",
"The install did not work.": "L'installazione non è riuscita.",
"The install did not work:": "L’installazione non ha funzionato:",
"The job could not start": "Impossibile avviare l’operazione",
"The key could not be imported": "Impossibile importare la chiave",
"The key in Settings has not been approved yet.": "La chiave nelle Impostazioni non è ancora stata approvata.",
"The key is entered and approved.": "La chiave è inserita e approvata.",
"The key was imported": "La chiave è stata importata",
"The key was not accepted. Check it, or make a new one on the provider's website.": "La chiave non è stata accettata. Controllala o creane una nuova sul sito del provider.",
"The key was refused": "La chiave è stata rifiutata",
"The key works": "La chiave funziona",
"The list could not be read.": "Impossibile leggere l’elenco.",
"The list of fonts is cleared": "L’elenco dei caratteri è stato svuotato",
"The lists are cut at 3000 entries each.": "Gli elenchi sono limitati a 3000 voci ciascuno.",
"The manifest does not ask for any extra library (no uses-library entry).": "Il manifest non richiede alcuna libreria aggiuntiva (nessuna voce uses-library).",
"The name in code type is the key. It is the same on every phone that has the setting.": "Il nome nel tipo codice è la chiave. È lo stesso su ogni telefono che ha l’impostazione.",
"The old code is gone. Anything you gave it to has to be given the new one.": "Il vecchio codice non esiste più. Tutto ciò a cui lo avevi dato deve ricevere quello nuovo.",
"The older storage permission some apps still check for.": "La vecchia autorizzazione di archiviazione che alcune app ancora controllano.",
"The pairing code has 6 digits": "Il codice di associazione ha 6 cifre",
"The password is used only for this archive, only while it is open. It is never saved.": "La password viene usata solo per questo archivio, solo mentre è aperto. Non viene mai salvata.",
"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "Il pacchetto di patch potrebbe essere danneggiato o creato per un Morphe più recente. Aggiorna la fonte in Fonti.",
"The patched APK is only saved. Install it from Patched APKs.": "L’APK modificato viene solo salvato. Installalo da APK modificati.",
"The patched APK was deleted after the install.": "L’APK modificato è stato eliminato dopo l’installazione.",
"The patcher could not be started": "Impossibile avviare il patcher",
"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Al patcher è mancata la memoria. Chiudi altre app e riprova, oppure attiva «Rimuovi le librerie native inutilizzate» nelle impostazioni del patcher.",
"The patcher stopped": "Il patcher si è fermato",
"The patcher stops and nothing is saved.": "Il patcher si ferma e non viene salvato nulla.",
"The patches could not be read": "Impossibile leggere le patch",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Le patch non supportano questa versione dell’app. Ottieni una versione supportata con Morphe Helper, oppure attiva «Modifica versioni non supportate» nelle impostazioni del patcher.",
"The paths could not be read.": "Impossibile leggere i percorsi.",
"The phone may still apply it. It is looked at again in a moment.": "Il telefono potrebbe comunque applicarlo. Verrà ricontrollato tra un momento.",
"The phone may still apply it. The list is read again in a moment.": "Il telefono potrebbe comunque applicarlo. L’elenco verrà riletto tra un momento.",
"The phone's browser": "Il browser del telefono",
"The project gives no description for this package.": "Il progetto non fornisce alcuna descrizione per questo pacchetto.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "I provider non supportano ufficialmente Android: lo strumento potrebbe non funzionare su tutti i telefoni. Se qualcosa non va, il Terminale ne mostra i messaggi esatti.",
"The pull did not finish": "La copia non è terminata",
"The push did not finish": "L’invio non è terminato",
"The quick brown fox jumps over the lazy dog.": "The quick brown fox jumps over the lazy dog.",
"The repository must be an https:// address": "Il repository deve essere un indirizzo https://",
"The request could not be sent": "Impossibile inviare la richiesta",
"The request could not start": "Impossibile avviare la richiesta",
"The research agent behind every Ask agent button, and the one the Application Updater asks to find an app. It reads the web and weighs what it finds to answer: what a hidden setting, a permission, a process, a log line or an app is. It is not a coding agent and it never changes anything on the phone. Perplexity is the default: it searches the web by itself and names its sources. Its key is set up in the Command-Line Interface tab.": "L'agente di ricerca dietro ogni pulsante Ask agent, e quello a cui l'aggiornamento app chiede di trovare un'app. Legge il web e valuta ciò che trova per rispondere: che cos'è un'impostazione nascosta, un permesso, un processo, una riga di log o un'app. Non è un agente di programmazione e non modifica mai nulla sul telefono. Perplexity è il predefinito: cerca da solo sul web e cita le fonti. La sua chiave si imposta nella scheda Command-Line Interface.",
"The resolution the device draws at, width x height in pixels.": "La risoluzione a cui il dispositivo disegna, larghezza x altezza in pixel.",
"The round checkmark button (when apps are selected)": "Il pulsante tondo con il segno di spunta (quando ci sono app selezionate)",
"The scan failed: unknown error": "Scansione non riuscita: errore sconosciuto",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "Lo schermo mostra per un momento le impostazioni di un’app dopo l’altra mentre si tocca Svuota cache per ogni app che ha ancora una cache non raggiungibile dai file. Una copertura mostra cosa succede, con un pulsante Annulla. Si ferma se lo schermo si spegne.",
"The search could not start": "Impossibile avviare la ricerca",
"The search did not work.": "La ricerca non è riuscita.",
"The search failed": "Ricerca non riuscita",
"The search failed.": "Ricerca non riuscita.",
"The search failed: unknown error": "La ricerca non è riuscita: errore sconosciuto",
