"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Poi concedi a questa app l’autorizzazione “Run commands in Termux environment” e verifica la connessione. Configurazione Termux, nelle impostazioni del Terminale, ti guida passo passo.",
"There are no saved lists to back up yet": "Non ci sono ancora liste salvate di cui fare il backup",
"There are no saved lists to back up yet; Restore works anyway.": "Non ci sono ancora liste salvate di cui fare il backup; il ripristino funziona comunque.",
