"These apps are currently selected for this action:": "Queste app sono attualmente selezionate per questa azione:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Queste app sono disinstallate ma le loro cartelle di dati sono ancora sul telefono. I dati delle app che spunti vengono eliminati definitivamente.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Queste app sono disinstallate. Senza Root l’app non può vedere quali hanno ancora dati, quindi cancellarle tutte è sicuro ma per alcune potrebbe non trovare nulla. I dati delle app che spunti vengono eliminati definitivamente.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Le release di queste app si trovano su siti che questa app non può controllare direttamente. Obtainium può monitorarle.",
"These files are too different to compare line by line. View each one instead.": "Questi file sono troppo diversi per essere confrontati riga per riga. Visualizzali singolarmente.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Proseguono quando il browser è chiuso. Pausa conserva ciò che è stato scaricato e Riprendi chiede al sito solo il resto (un sito che non può farlo ricomincia il file).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Verranno saltate a meno che tu non modifichi comunque, il che può fallire o danneggiare l’app.",
