"This agent": "Questo agente",
"This agent has no sign-in tool": "Questo agente non ha uno strumento di accesso",
"This app": "Questa app",
"This app (sandbox)": "Quest’app (sandbox)",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Questa app non può leggere la memoria. Concedi l'accesso a tutti i file oppure scegli un file di carattere a mano (non serve alcun accesso).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Quest’app non richiede uno specifico touchscreen, tastiera o navigazione (non ha alcuna voce uses-configuration), quindi funziona con ciò che ha questo telefono.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Quest’app non elenca alcuna funzionalità hardware o software di cui ha bisogno (nessuna voce uses-feature).",
"This app has no activities.": "Quest’app non ha activity.",
"This app may not run commands in Termux yet.": "Quest’app potrebbe non poter ancora eseguire comandi in Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Questa app ora ha una propria chiave ADB privata. Tocca il badge della modalità per i dettagli.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Impossibile leggere il codice di questa app (non ne ha, o il file non è leggibile), quindi non si può dire nulla sui tracker.",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "Il codice di autorizzazione di questa app. Per ora nulla lo accetta: è conservato qui per dopo. Viene creato su questo telefono, resta su questo telefono e puoi sostituirlo in qualsiasi momento.",
"This app's own shell - no root, ADB or package manager.": "La shell propria di quest’app: niente Root, ADB o gestore dei pacchetti.",
"This app's own storage (private)": "Archivio proprio dell'app (privato)",
"This app's own user and group id": "ID utente e gruppo di quest’app",
"This app’s key · 2048-bit RSA · in secure hardware": "Chiave di questa app · RSA a 2048 bit · in hardware sicuro",
"This app’s key · 2048-bit RSA · in the Android Keystore": "Chiave di questa app · RSA a 2048 bit · nell’Android Keystore",
"This archive is view-only": "Questo archivio è di sola visualizzazione",
"This build": "Questa build",
"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "Questa versione dell’app non contiene il motore Morphe, quindi la modifica con patch non è disponibile. Fonti, ricerca della community e download funzionano comunque. Installa una versione di rilascio dell’app per modificare.",
"This build of the app does not contain the Morphe engine. Install a release build.": "Questa versione dell’app non contiene il motore Morphe. Installa una versione di rilascio.",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Questo può interrompere la connessione ADB usata da questa app, quindi potresti non riuscire a ripristinarlo da qui.",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "Questo può impedirti di usare parti del telefono (lo schermo, la tastiera o l’accessibilità).",
"This cannot be undone.": "Non si può annullare.",
