"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Quando elimina i duplicati, SD Maid decide quale file tenere controllando ogni criterio in ordine. Il primo criterio che dà un chiaro vincitore determina il risultato. Trascina per riordinare, tocca per cambiare modalità.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "Quando la fonte scelta non ha la versione o non funziona, Questa versione, Più recente e Tutte le versioni passano alla fonte successiva, nell’ordine sopra, finché una non risponde.",
